    """Greedily place highest-pressure models where their resulting KVPR is smallest."""
    placement = {gpu_id: [] for gpu_id in range(gpu_num)}
    remaining = [GPU_MEM_SIZE] * gpu_num
    pressure = [0.0] * gpu_num

    for model in sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True):
        weight = model.req_rate / model.slo
        best_gpu = None
        best_kvpr = float("inf")

        for gpu_id in range(gpu_num):
            free_after = remaining[gpu_id] - model.model_size
            if free_after >= 0:
                kvpr_after = (
                    (pressure[gpu_id] + weight) / free_after
                    if free_after > 0 else float("inf")
                )
                if kvpr_after < best_kvpr:
                    best_kvpr = kvpr_after
                    best_gpu = gpu_id

        if best_gpu is None:
            raise ValueError(
                f"Unable to place model of size {model.model_size} GB; "
                f"remaining memory: {remaining}"
            )

        placement[best_gpu].append(model)
        remaining[best_gpu] -= model.model_size
        pressure[best_gpu] += weight

    return placement
